"use client"

/**
 * Text3DFlip — timed keyword carousel with Magic-style slab geometry (see magicui.design).
 *
 * Layout / motion notes (from CSS 3D + Motion behaviour):
 * - Rotating around X inside a perspective parent moves the projected text vertically — that's
 *   parallax from perspective, not just “springs”.
 * - Remounting flip nodes each phrase resets transforms and exaggerates pops; pivots stay stable
 *   per word slot (`key={wi}`).
 * - Springs can still subtly overshoot string transform targets — tweens stop at exact end values.
 */

import React, {
  Fragment,
  memo,
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type CSSProperties,
  type ElementType,
} from "react"
import { flushSync } from "react-dom"
import {
  useAnimate,
  type ValueAnimationTransition,
} from "motion/react"

import { cn } from "@/lib/utils"

const ROTATION_MAP = {
  top: "rotateX(90deg)",
  right: "rotateY(90deg)",
  bottom: "rotateX(-90deg)",
  left: "rotateY(-90deg)",
} as const

const SECOND_FACE_TRANSFORMS = {
  top: "rotateX(-90deg) translateZ(0.5lh)",
  right:
    "rotateY(90deg) translateX(50%) rotateY(-90deg) translateX(-50%) rotateY(-90deg) translateX(50%)",
  bottom: "rotateX(90deg) translateZ(0.5lh)",
  left:
    "rotateY(90deg) translateX(50%) rotateY(-90deg) translateX(50%) rotateY(-90deg) translateX(50%)",
} as const

const FRONT_FACE_TRANSFORMS = {
  top: "translateZ(0.5lh)",
  bottom: "translateZ(0.5lh)",
  left: "rotateY(90deg) translateX(50%) rotateY(-90deg)",
  right: "rotateY(-90deg) translateX(50%) rotateY(90deg)",
} as const

const CONTAINER_TRANSFORMS = {
  top: "translateZ(-0.5lh)",
  bottom: "translateZ(-0.5lh)",
  left: "rotateY(90deg) translateX(50%) rotateY(-90deg)",
  right: "rotateY(90deg) translateX(50%) rotateY(-90deg)",
} as const

/** Tweens hit exact endpoints (no physics overshoot on transform strings). */
const FLIP_TWEEN: ValueAnimationTransition = {
  type: "tween",
  duration: 0.4,
  ease: [0.33, 0, 0.17, 1],
}

const DEFAULT_DWELL_MS = 4800
const MIN_WIDTH_SLOP_PX = 12

type RotateDirection = keyof typeof ROTATION_MAP

function splitWords(phrase: string): { text: string; needsSpaceAfter: boolean }[] {
  if (!phrase.trim()) return []
  const parts = phrase.split(" ")
  return parts.map((text, index) => ({
    text,
    needsSpaceAfter: index < parts.length - 1,
  }))
}

function collectFlipRoots(root: HTMLElement | null): HTMLElement[] {
  if (!root) return []
  return [...root.querySelectorAll(".text-3d-flip-char")] as HTMLElement[]
}

function sleep(ms: number) {
  return new Promise<void>((r) => {
    window.setTimeout(r, ms)
  })
}

export interface Text3DFlipProps {
  keywords: readonly string[]
  flipIntervalMs?: number
  staggerDuration?: number
  staggerFrom?: "first" | "last" | "center" | number | "random"
  as?: ElementType
  className?: string
  textClassName?: string
  flipTextClassName?: string
  transition?: ValueAnimationTransition | Record<string, unknown>
  rotateDirection?: RotateDirection
  style?: CSSProperties
}

const Text3DFlip = ({
  keywords,
  flipIntervalMs = DEFAULT_DWELL_MS,
  staggerDuration = 0.065,
  staggerFrom = "first",
  as: ElementTag = "p",
  className,
  textClassName,
  flipTextClassName,
  transition = FLIP_TWEEN,
  rotateDirection = "right",
  style,
  ...props
}: Text3DFlipProps) => {
  const [scopeRef, scopeAnimate] = useAnimate()
  const cancelledRef = useRef(false)
  const runningRef = useRef(false)

  const keywordsLenRef = useRef(keywords.length)
  keywordsLenRef.current = keywords.length

  const safeLen = Math.max(keywords.length, 1)
  const cycleEnabled = keywords.length >= 2
  const [phraseIndex, setPhraseIndex] = useState(0)

  const text = keywords[phraseIndex % safeLen] ?? ""
  const wordSlots = useMemo(() => splitWords(text), [text])

  const totalTiles = wordSlots.length

  const getStaggerDelay = useCallback(
    (tileIndex: number, totalTiles_: number) => {
      if (staggerFrom === "first") return tileIndex * staggerDuration
      if (staggerFrom === "last") return (totalTiles_ - 1 - tileIndex) * staggerDuration
      if (staggerFrom === "center") {
        const center = Math.floor(totalTiles_ / 2)
        return Math.abs(center - tileIndex) * staggerDuration
      }
      if (staggerFrom === "random") {
        const randomIndex = Math.floor(Math.random() * totalTiles_)
        return Math.abs(randomIndex - tileIndex) * staggerDuration
      }
      return Math.abs(staggerFrom - tileIndex) * staggerDuration
    },
    [staggerFrom, staggerDuration]
  )

  const keywordsFingerprint = useMemo(() => [...keywords].join("\u037e"), [keywords])

  const transitionRef = useRef(transition)
  transitionRef.current = transition

  const rotationTransform = ROTATION_MAP[rotateDirection]

  const probeRef = useRef<HTMLSpanElement | null>(null)
  const [reservedMinPx, setReservedMinPx] = useState(0)

  const remeasureWidths = useCallback(() => {
    const probe = probeRef.current
    if (!probe) return

    let max = 0
    for (const phrase of keywords) {
      if (!phrase.trim()) continue
      probe.textContent = phrase
      max = Math.max(max, probe.offsetWidth)
    }
    probe.textContent = ""
    setReservedMinPx(Math.ceil(max + MIN_WIDTH_SLOP_PX))
  }, [keywords])

  useLayoutEffect(() => {
    remeasureWidths()
  }, [remeasureWidths, className, textClassName, keywordsFingerprint])

  useEffect(() => {
    if (typeof document === "undefined") return undefined
    const fonts = document.fonts
    if (!fonts?.ready) return undefined
    let cancelled = false
    void fonts.ready.then(() => {
      if (!cancelled) remeasureWidths()
    })
    return () => {
      cancelled = true
    }
  }, [remeasureWidths])

  useEffect(() => {
    if (typeof window === "undefined") return undefined
    const onResize = () => {
      remeasureWidths()
    }
    window.addEventListener("resize", onResize, { passive: true })
    return () => window.removeEventListener("resize", onResize)
  }, [remeasureWidths])

  useEffect(() => {
    cancelledRef.current = false
    if (!cycleEnabled || totalTiles === 0) return undefined

    async function loop() {
      while (!cancelledRef.current && keywordsLenRef.current >= 2) {
        await sleep(Math.max(flipIntervalMs, 1800))

        if (cancelledRef.current || runningRef.current) continue

        const root = scopeRef.current as HTMLElement | null
        const pivotsOut = collectFlipRoots(root)
        if (pivotsOut.length === 0) continue

        runningRef.current = true

        try {
          const tg = pivotsOut.length
          const delays = Array.from({ length: tg }, (_, i) => getStaggerDelay(i, tg))
          const t = transitionRef.current as object

          await Promise.all(
            pivotsOut.map((el, i) =>
              scopeAnimate(el, { transform: rotationTransform }, {
                ...t,
                delay: delays[i] ?? 0,
              }),
            ),
          )

          if (cancelledRef.current) return

          // Edge-on → swap phrase (stable pivots preserve Motion transform at ~90deg)
          flushSync(() => {
            const L = keywordsLenRef.current || 1
            setPhraseIndex((i) => (i + 1) % L)
          })

          if (cancelledRef.current) return

          const pivotsIn = collectFlipRoots(scopeRef.current as HTMLElement | null)
          if (pivotsIn.length === 0) continue

          await Promise.all(
            pivotsIn.map((el, i) =>
              scopeAnimate(el, { transform: "rotateX(0deg) rotateY(0deg)" }, {
                ...t,
                delay: delays[i] ?? 0,
              }),
            ),
          )
        } finally {
          runningRef.current = false
        }
      }
    }

    void loop()
    return () => {
      cancelledRef.current = true
    }
  }, [
    cycleEnabled,
    flipIntervalMs,
    getStaggerDelay,
    keywordsFingerprint,
    rotationTransform,
    totalTiles,
  ])

  if (keywords.length === 0) return null

  return (
    <>
      <span
        ref={probeRef}
        aria-hidden="true"
        className={cn(
          "pointer-events-none fixed left-[-10000px] top-0 z-[-1] inline-block whitespace-nowrap",
          className,
          textClassName,
        )}
      />
      <ElementTag
        className={cn(
          "relative inline-flex max-w-max flex-nowrap shrink-0 items-center whitespace-nowrap align-middle",
          className,
        )}
        {...props}
        style={{
          ...style,
          minWidth: reservedMinPx > 0 ? `${reservedMinPx}px` : undefined,
        }}
      >
        <span className="sr-only">{text}</span>
        {/*
          perspective-origin top: keeps the headline line feeling anchored while rotateX swings
          (see CSS-Tricks / MDN perspective-origin).
        */}
        <span
          ref={scopeRef}
          className="relative inline-flex flex-nowrap items-center gap-0 perspective-[960px] perspective-origin-[50%_0%] transform-3d"
        >
          {wordSlots.map((slot, wi) => (
            <Fragment key={`w-${wi}`}>
              <WordFlipTile
                word={slot.text}
                rotateDirection={rotateDirection}
                textClassName={textClassName}
                flipTextClassName={flipTextClassName}
              />
              {slot.needsSpaceAfter && <span className="shrink-0 whitespace-pre"> </span>}
            </Fragment>
          ))}
        </span>
      </ElementTag>
    </>
  )
}

interface WordFlipTileProps {
  word: string
  textClassName?: string
  flipTextClassName?: string
  rotateDirection: RotateDirection
}

const WordFlipTile = memo(
  ({
    word,
    textClassName,
    flipTextClassName,
    rotateDirection,
  }: WordFlipTileProps) => (
    <span
      className="text-3d-flip-char inline-block shrink-0 self-center origin-center transform-3d will-change-transform"
    >
      <span
        className="relative inline-block origin-center transform-3d"
        style={{ transform: CONTAINER_TRANSFORMS[rotateDirection] }}
      >
        <span
          className={cn(
            "relative block w-max whitespace-pre text-left font-[inherit] h-lh backface-hidden",
            textClassName,
          )}
          style={{
            WebkitFontSmoothing: "antialiased",
            transform: FRONT_FACE_TRANSFORMS[rotateDirection],
          }}
        >
          {word}
        </span>
        <span
          aria-hidden="true"
          className={cn(
            "pointer-events-none absolute left-0 top-0 block w-max whitespace-pre text-left font-[inherit] h-lh backface-hidden",
            flipTextClassName,
          )}
          style={{
            WebkitFontSmoothing: "antialiased",
            transform: SECOND_FACE_TRANSFORMS[rotateDirection],
          }}
        >
          {word}
        </span>
      </span>
    </span>
  ),
)

WordFlipTile.displayName = "WordFlipTile"
Text3DFlip.displayName = "Text3DFlip"

export { Text3DFlip }
